DROP TABLE IF EXISTS `inventory_physical_counts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_physical_counts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `session_id` bigint unsigned NOT NULL,
  `asset_id` bigint unsigned NOT NULL,
  `counted_by` bigint unsigned NOT NULL,
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `actual_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `counted_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `inventory_physical_counts_session_id_asset_id_unique` (`session_id`,`asset_id`),
  KEY `inventory_physical_counts_asset_id_foreign` (`asset_id`),
  KEY `inventory_physical_counts_counted_by_foreign` (`counted_by`),
  CONSTRAINT `inventory_physical_counts_asset_id_foreign` FOREIGN KEY (`asset_id`) REFERENCES `inventory_assets` (`asset_id`),
  CONSTRAINT `inventory_physical_counts_counted_by_foreign` FOREIGN KEY (`counted_by`) REFERENCES `users` (`id`),
  CONSTRAINT `inventory_physical_counts_session_id_foreign` FOREIGN KEY (`session_id`) REFERENCES `physical_count_sessions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
